import type { ComponentProps } from "@solidjs/web";
import { cn } from "~/lib/utils.ts";
import IconUnfoldMore from "~icons/hugeicons/unfold-more";
import type { Component } from "solid-js";

import { omit } from "solid-js";

type NativeSelectProps =
  & Omit<ComponentProps<"select">, "size">
  & { size?: "sm" | "default" };

const NativeSelect: Component<NativeSelectProps> = (props) => {
  const others = omit(props, "class", "size");
  return (
    <div
      class={cn(
        "group/native-select relative w-fit has-[select:disabled]:opacity-50",
        props.class,
      )}
      data-slot="native-select-wrapper"
      data-size={props.size ?? "default"}
    >
      <select
        data-slot="native-select"
        data-size={props.size ?? "default"}
        class="h-8 w-full min-w-0 appearance-none rounded-lg border border-input bg-transparent py-1 pr-8 pl-2.5 text-sm transition-colors select-none placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground dark:bg-input/30 dark:hover:bg-input/50 focus-visible:border-ring focus-visible:ring-3 focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-3 aria-invalid:ring-destructive/20 dark:aria-invalid:border-destructive/50 dark:aria-invalid:ring-destructive/40 data-[size=sm]:h-7 data-[size=sm]:rounded-[min(var(--radius-md),10px)] data-[size=sm]:py-0.5 outline-none disabled:pointer-events-none disabled:cursor-not-allowed"
        {...others}
      />
      <IconUnfoldMore
        class="top-1/2 right-2.5 size-4 -translate-y-1/2 text-muted-foreground pointer-events-none absolute select-none"
        aria-hidden="true"
        data-slot="native-select-icon"
      />
    </div>
  );
};

const NativeSelectOption: Component<ComponentProps<"option">> = (props) => {
  const others = omit(props, "class");
  return (
    <option
      data-slot="native-select-option"
      class={cn("bg-[Canvas] text-[CanvasText]", props.class)}
      {...others}
    />
  );
};

const NativeSelectOptGroup: Component<ComponentProps<"optgroup">> = (props) => {
  const others = omit(props, "class");
  return (
    <optgroup
      data-slot="native-select-optgroup"
      class={cn("bg-[Canvas] text-[CanvasText]", props.class)}
      {...others}
    />
  );
};

export type { NativeSelectProps };
export { NativeSelect, NativeSelectOptGroup, NativeSelectOption };
